INSERT INTO `components_blog_contents` VALUES (99,'<p>Compartimos excelente #CharlaEntreAmigos, con el tema; Sistemas para el #Retiro.<br>Nuestra invitada, Elena Torres, nos aclaró todas las dudas sobre trámites de pensiones, ahorros y estrategias para la #jubilación.<br>#DerexPensandoFueraDeLaCasa</p>'),(100,'<p>Campana sobre campana y sobre campana uunaaaa … está canción fue parte de los villancicos que sonaron en la Posada Infantil que organizamos en Serena Nogales.</p><p><br>Nos dio mucho gusto compartir pastel, repartir dulces y pegarle a la piñata, una tradición que repetimos cada año.<br>&nbsp;</p><p>En #Derex creemos que crear momentos de convivencia, nos ayuda a estrechar lazos de amistad y armonía entre vecinos.</p>'),(101,'<p>Cerramos el ciclo #GuadalupeReyes compartiendo #Rosca en nuestras oficinas #Derex</p>'),(102,'<p>¡Mira lo que aprendimos! Tuvimos un Taller de separación de residuos llamado biciclando en donde aprendimos muchos tip’s ecológicos para separar residuos y clasificar basura en nuestra #ComunidadDerexC+ Praga en Hermosillo. Motivamos a nuestros residentes a mantener un entorno más limpio y sostenible. Agradecemos al Centro de Economía Circular por mostrarnos este innovador programa #PensandoFueraDeLaCasa</p>'),(117,'<p><span style=\"font-family:&quot;Arial&quot;,sans-serif;\">¡Música para nuestros oídos! Tuvimos un concierto didáctico para niños y niñas con el quinteto de aliento “Solistas de Sonora” en #Siena #Hermosillo.&nbsp;</span></p><p><span style=\"font-family:&quot;Arial&quot;,sans-serif;\">La música cura el alma y conecta nuestras emociones, motivamos a las infancias&nbsp;<span> </span>a tocar un instrumento musical. ¡Gracias al quinteto de viento Solistas de Sonora por compartir su talento y pasión! #ComunidadesDerexC+ #PensandoFueraDeLaCasa</span></p>'),(118,'<p>¡Mira lo que aprendimos! Tuvimos un Taller de separación de residuos llamado biciclando en donde aprendimos muchos tip’s ecológicos para separar residuos y clasificar basura en nuestra #ComunidadDerexC+ Praga en Hermosillo. Motivamos a nuestros residentes a mantener un entorno más limpio y sostenible. Agradecemos al Centro de Economía Circular por mostrarnos este innovador programa #PensandoFueraDeLaCasa</p>'),(119,'<p>¡Fueron muchos niños a nuestra Clase de Karate en #Serena Nogales!, realizamos estiramientos y acondicionamiento físico. Estamos seguros de que las actividades al aire libre son positivas para la convivencia y la salud de todos. Creamos #TejidoComunitario #ComunidadesDerexC+ #PensandoFueraDeLaCasa</p>'),(122,'<p>¡Que bellas y alegres son nuestras #FiestasPatrias! Estuvimos de gala en la #ComunidadDerexC+ #Praga. La Tečka se vistió de mil colores con la presencia del Ballet Folckórico “Compañía Tradición Mestiza” que dirige el Mtro Amador. Presenciamos bailes típicos, comimos antojitos mexicanos y jugamos a la lotería. #AmorPorMéxico #VivaMéxico</p>'),(130,'<p>¡Fueron muchos niños a nuestra Clase de Karate en #Serena Nogales!, realizamos estiramientos y acondicionamiento físico. Estamos seguros de que las actividades al aire libre son positivas para la convivencia y la salud de todos. Creamos #TejidoComunitario #ComunidadesDerexC+ #PensandoFueraDeLaCasa</p>'),(134,'<p><span style=\"font-family:&quot;Arial&quot;,sans-serif;\">¡Música para nuestros oídos! Tuvimos un concierto didáctico para niños y niñas con el quinteto de aliento “Solistas de Sonora” en #Siena #Hermosillo.&nbsp;</span></p><p><span style=\"font-family:&quot;Arial&quot;,sans-serif;\">La música cura el alma y conecta nuestras emociones, motivamos a las infancias&nbsp;<span> </span>a tocar un instrumento musical. ¡Gracias al quinteto de viento Solistas de Sonora por compartir su talento y pasión! #ComunidadesDerexC+ #PensandoFueraDeLaCasa</span></p>'),(136,'<p>¡Que bellas y alegres son nuestras #FiestasPatrias! Estuvimos de gala en la #ComunidadDerexC+ #Praga. La Tečka se vistió de mil colores con la presencia del Ballet Folckórico “Compañía Tradición Mestiza” que dirige el Mtro Amador. Presenciamos bailes típicos, comimos antojitos mexicanos y jugamos a la lotería. #AmorPorMéxico #VivaMéxico</p>'),(138,'<p>Campana sobre campana y sobre campana uunaaaa … está canción fue parte de los villancicos que sonaron en la Posada Infantil que organizamos en Serena Nogales.</p><p><br>Nos dio mucho gusto compartir pastel, repartir dulces y pegarle a la piñata, una tradición que repetimos cada año.<br>&nbsp;</p><p>En #Derex creemos que crear momentos de convivencia, nos ayuda a estrechar lazos de amistad y armonía entre vecinos.</p>'),(140,'<p>Compartimos excelente #CharlaEntreAmigos, con el tema; Sistemas para el #Retiro.<br>Nuestra invitada, Elena Torres, nos aclaró todas las dudas sobre trámites de pensiones, ahorros y estrategias para la #jubilación.<br>#DerexPensandoFueraDeLaCasa</p>'),(141,'<p>Cerramos el ciclo #GuadalupeReyes compartiendo #Rosca en nuestras oficinas #Derex</p>');
